(async () => {
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));

  /* Рисуем настоящие снимки прямо здесь: большие, как с телефона (12 Мп),
     чтобы обработка была не игрушечной. Разные цвета — чтобы на плитках было
     видно, что порядок сохраняется и первое фото действительно первое. */
  const colors = ['#e11d48', '#0ea5e9', '#16a34a', '#f59e0b', '#7c3aed'];
  const files = [];
  for (let i = 0; i < colors.length; i += 1) {
    const canvas = document.createElement('canvas');
    canvas.width = 4000;
    canvas.height = 3000;
    const g = canvas.getContext('2d');
    g.fillStyle = colors[i];
    g.fillRect(0, 0, canvas.width, canvas.height);
    /* Шум: одноцветный прямоугольник сжимается в килобайт и мерил бы не то. */
    for (let n = 0; n < 4000; n += 1) {
      g.fillStyle = `hsl(${(n * 7) % 360} 70% ${30 + (n % 40)}%)`;
      g.fillRect(Math.random() * 4000, Math.random() * 3000, 60, 60);
    }
    g.fillStyle = '#fff';
    g.font = 'bold 600px sans-serif';
    g.fillText(String(i + 1), 1700, 1900);
    const blob = await new Promise((res) => canvas.toBlob(res, 'image/jpeg', 0.92));
    files.push(new File([blob], `photo-${i + 1}.jpg`, { type: 'image/jpeg' }));
  }

  const input = [...document.querySelectorAll('input[type=file]')].find((n) => n.accept.includes('image'));
  if (!input) return { error: 'поле выбора файла не найдено' };
  const dt = new DataTransfer();
  for (const file of files) dt.items.add(file);
  input.files = dt.files;
  input.dispatchEvent(new Event('change', { bubbles: true }));

  /* Ждём, пока все пять пройдут через поток обработки и загрузятся. */
  for (let i = 0; i < 60; i += 1) {
    await wait(250);
    const busy = document.querySelectorAll('.pmb__busy').length;
    const done = document.querySelectorAll('.pmb__img').length;
    if (busy === 0 && done >= 5) break;
  }

  /* Заполняем карточку, чтобы её можно было сохранить. */
  const set = (selector, value) => {
    const node = document.querySelector(selector);
    if (!node) return;
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(node, value);
    node.dispatchEvent(new Event('input', { bubbles: true }));
  };
  set('[data-field="name"]', 'Сыр «Гауда» фермерский');
  set('[data-field="qty"]', '24');
  set('[data-field="cost"]', '195.00');
  set('[data-field="markup"]', '35');
  await wait(400);
  return { photos: document.querySelectorAll('.pmb__img').length };
})()

(async () => {
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  const canvas = document.createElement('canvas');
  canvas.width = 2400; canvas.height = 1800;
  const g = canvas.getContext('2d');
  g.fillStyle = '#0ea5e9'; g.fillRect(0, 0, 2400, 1800);
  for (let n = 0; n < 2000; n += 1) { g.fillStyle = `hsl(${(n * 11) % 360} 65% 45%)`; g.fillRect(Math.random() * 2400, Math.random() * 1800, 40, 40); }
  const blob = await new Promise((res) => canvas.toBlob(res, 'image/jpeg', 0.9));
  const input = [...document.querySelectorAll('input[type=file]')].find((n) => n.accept.includes('image'));
  const dt = new DataTransfer();
  dt.items.add(new File([blob], 'one.jpg', { type: 'image/jpeg' }));
  input.files = dt.files;
  input.dispatchEvent(new Event('change', { bubbles: true }));
  for (let i = 0; i < 40; i += 1) { await wait(200); if (!document.querySelector('.pmb__busy')) break }

  const set = (selector, value) => {
    const node = document.querySelector(selector);
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(node, value);
    node.dispatchEvent(new Event('input', { bubbles: true }));
  };
  set('[data-field="name"]', 'Творог домашний 5%');
  set('[data-field="qty"]', '12');
  set('[data-field="cost"]', '80');
  set('[data-field="markup"]', '40');
  await wait(300);
  [...document.querySelectorAll('.dsk__btn')].find((b) => b.textContent.trim() === 'Сохранить и следующий')?.click();
  await wait(2500);
  return { recent: document.querySelectorAll('.ppg__recent-row').length };
})()
